def seed_courses_templates(apps, schema_editor):
    Course = apps.get_model("evaluation", "Course")
    StudentProfile = apps.get_model("evaluation", "StudentProfile")
    Project = apps.get_model("evaluation", "Project")
    EvaluationTemplate = apps.get_model("evaluation", "EvaluationTemplate")
    EvaluationCriterion = apps.get_model("evaluation", "EvaluationCriterion")
    EvaluationSubmission = apps.get_model("evaluation", "EvaluationSubmission")

    courses = {}
    for name, code in COURSES:
        course, _ = Course.objects.get_or_create(
            code=code,
            defaults={
                "name": name,
                "description": f"{name} FYP evaluation course grouping.",
                "is_active": True,
            },
        )
        courses[code] = course

    def infer_course(text):
        text = (text or "").lower()
        if "artificial" in text or "ai" in text:
            return courses["AI"]
        if "cyber" in text or "security" in text:
            return courses["CYB"]
        if "software" in text:
            return courses["SE"]
        if "multimedia" in text:
            return courses["MM"]
        if "network" in text:
            return courses["NET"]
        if "computer" in text:
            return courses["CS"]
        return courses["IT"]

    for student in StudentProfile.objects.filter(course__isnull=True):
        student.course = infer_course(student.programme)
        if not student.programme and student.course:
            student.programme = student.course.name
        student.save(update_fields=["course", "programme"])

    for project in Project.objects.filter(course__isnull=True).select_related("leader"):
        project.course = project.leader.course or infer_course(project.programme)
        if not project.programme and project.course:
            project.programme = project.course.name
        project.save(update_fields=["course", "programme"])

    template = EvaluationTemplate.objects.filter(is_active=True).first()
    if not template:
        template = EvaluationTemplate.objects.first()
    if not template:
        template = EvaluationTemplate.objects.create(
            title="Default FYP Evaluation Template",
            description="Default dynamic rubric matching the original 95-mark evaluation structure.",
            is_active=True,
        )
    else:
        EvaluationTemplate.objects.exclude(id=template.id).update(is_active=False)
        template.is_active = True
        template.save(update_fields=["is_active"])

    if not EvaluationCriterion.objects.filter(template=template).exists():
        for name, description, max_score, order in DEFAULT_CRITERIA:
            EvaluationCriterion.objects.create(
                template=template,
                name=name,
                description=description,
                max_score=max_score,
                order=order,
            )

    EvaluationSubmission.objects.filter(template__isnull=True).update(template=template)


